class Sensor:
    def __init__(self, path: str) -> None:
        self._handle = _LIB.sensor_open(path.encode())
        if not self._handle:
            raise OSError('sensor_open failed')
    def __enter__(self) -> 'Sensor': return self
    def __exit__(self, *exc) -> None: self.close()
    def close(self) -> None:
        if self._handle:
            _LIB.sensor_close(self._handle)
            self._handle = None
